// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MONEY_BOX c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new MONEY_BOX();
        c.SetLogFile(address(log_));
        c.SetMinSum(1);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 lockTime, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        lockTime = bound(lockTime, 1, 365 days);
        amount = bound(amount, 1, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        (uint unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime > block.timestamp);
    }
}
